import{_ as t,o as i,c as s,ao as a}from"./chunks/framework.DAbzcW3k.js";const g=JSON.parse('{"title":"Inputs","description":"","frontmatter":{},"headers":[],"relativePath":"inputs.md","filePath":"inputs.md","lastUpdated":null}'),o={name:"inputs.md"};function n(d,e,l,r,h,c){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="Inputs" tabindex="-1">Inputs <a class="header-anchor" href="#Inputs" aria-label="Permalink to &quot;Inputs {#Inputs}&quot;">​</a></h1><p>All inputs are optional. Each method has two inputs:</p><ul><li><p><code>_model</code> is the 3D volume, for example the result of an inversion.</p></li><li><p><code>_data</code> is the measured dataset for the same method.</p></li></ul><table tabindex="0"><thead><tr><th style="text-align:right;">Input</th><th style="text-align:right;">Formats</th><th style="text-align:right;">TerraScope shows</th></tr></thead><tbody><tr><td style="text-align:right;"><code>MT_model</code></td><td style="text-align:right;">ModEM/WS <code>.rho</code>, jif3D <code>.nc</code></td><td style="text-align:right;">A 3D resistivity model</td></tr><tr><td style="text-align:right;"><code>MT_data</code></td><td style="text-align:right;">ModEM <code>.dat</code>, jif3D <code>.nc</code></td><td style="text-align:right;">The MT sites. This file also georeferences the model.</td></tr><tr><td style="text-align:right;"><code>gravity_model</code></td><td style="text-align:right;"><code>.xyz</code>, <code>.vox</code>, jif3D <code>.nc</code></td><td style="text-align:right;">A 3D density or density-contrast model</td></tr><tr><td style="text-align:right;"><code>gravity_data</code></td><td style="text-align:right;"><code>.xyz</code>, jif3D <code>.nc</code> (mGal)</td><td style="text-align:right;">The gravity stations, at the station elevation</td></tr><tr><td style="text-align:right;"><code>magnetic_model</code></td><td style="text-align:right;"><code>.xyz</code>, <code>.vox</code>, jif3D <code>.nc</code></td><td style="text-align:right;">A 3D magnetic susceptibility model</td></tr><tr><td style="text-align:right;"><code>magnetic_data</code></td><td style="text-align:right;"><code>.xyz</code>, jif3D <code>.nc</code> (nT)</td><td style="text-align:right;">The magnetic measurement points, ground or airborne</td></tr><tr><td style="text-align:right;"><code>seismic_data</code></td><td style="text-align:right;">SEG-Y, one path or a list</td><td style="text-align:right;">A vertical 2D seismic section along each profile, and the model section along the same profile</td></tr><tr><td style="text-align:right;"><code>shapefiles</code></td><td style="text-align:right;">Any <code>.shp</code></td><td style="text-align:right;">A geological map layer. Each entry has its own <code>color</code>, <code>width</code> and <code>alpha</code>.</td></tr></tbody></table><h2 id="What-you-get" tabindex="-1">What you get <a class="header-anchor" href="#What-you-get" aria-label="Permalink to &quot;What you get {#What-you-get}&quot;">​</a></h2><p>What does the scene show? That depends on the inputs that you give:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Inputs</th><th style="text-align:right;">Result</th></tr></thead><tbody><tr><td style="text-align:right;">None</td><td style="text-align:right;">An empty 3D view. Its extent comes from the map data or the seismic profiles, if you give them.</td></tr><tr><td style="text-align:right;"><code>MT_model</code> only</td><td style="text-align:right;">The model in its local coordinates. Georeferenced overlays are not shown.</td></tr><tr><td style="text-align:right;"><code>MT_model</code> and <code>MT_data</code></td><td style="text-align:right;">The model, georeferenced into <code>coordinate.target_crs</code></td></tr><tr><td style="text-align:right;">A jif3D <code>.nc</code> <code>MT_model</code></td><td style="text-align:right;">The model, georeferenced from <code>coordinate.jif3d_crs</code> (default EPSG:3067)</td></tr><tr><td style="text-align:right;">A gravity or magnetic model, with an MT model</td><td style="text-align:right;">The model, resampled onto the MT mesh. You can compare the physical properties cell by cell.</td></tr><tr><td style="text-align:right;">A gravity or magnetic model, without an MT model</td><td style="text-align:right;">The model on a mesh made from its own coordinates</td></tr></tbody></table><p>Why does a ModEM model need its data file? A ModEM <code>.rho</code> file gives the cells in metres from an origin, but it does not give the location of that origin. The <code>.dat</code> file gives it.</p><h2 id="Density-units-and-density-contrast" tabindex="-1">Density units and density contrast <a class="header-anchor" href="#Density-units-and-density-contrast" aria-label="Permalink to &quot;Density units and density contrast {#Density-units-and-density-contrast}&quot;">​</a></h2><p>Many inversions give a density contrast, not an absolute density. TerraScope shows the values as they are in the file. A contrast model has the label <code>Δρ</code>.</p><p>To show absolute density, set the background density in the launcher:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    density_reference_kg_m3 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2670.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># TerraScope adds this value to each cell.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    density_units </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :g_cc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or :kg_m3.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span></code></pre></div><h2 id="jif3D-NetCDF-files" tabindex="-1">jif3D NetCDF files <a class="header-anchor" href="#jif3D-NetCDF-files" aria-label="Permalink to &quot;jif3D NetCDF files {#jif3D-NetCDF-files}&quot;">​</a></h2><p>TerraScope reads a <code>.nc</code> file in any model or data input as <a href="https://git.tu-berlin.de/applied-geophysics/jif3d" target="_blank" rel="noreferrer">jif3D</a> output. The variable in the file gives the property:</p><ul><li><p>Models: <code>Conductivity</code> (shown as resistivity), <code>Density</code> or <code>Susceptibility</code>.</p></li><li><p>Data: MT impedances, <code>Scalar_gravity</code> or the total field <code>T</code>.</p></li></ul><p>A jif3D mesh is in absolute projected metres. Thus an MT model does not need a data file to be georeferenced. If the inversion did not use the CRS of the scene, set <code>coordinate.jif3d_crs</code>.</p><h2 id="Shapefiles" tabindex="-1">Shapefiles <a class="header-anchor" href="#Shapefiles" aria-label="Permalink to &quot;Shapefiles {#Shapefiles}&quot;">​</a></h2><p>You can add any shapefile and as many shapefiles as you need. TerraScope draws them on the surface, above the model:</p><ul><li><p>Polyline features, for example fault traces, lithological contacts and shear zones.</p></li><li><p>Polygon features as their boundaries, for example geological units and licence areas.</p></li></ul><p>TerraScope does not draw point features, for example outcrop observations or drill-hole collars.</p><p>If the shapefile has a <code>.prj</code> file, TerraScope reads the CRS from it and reprojects the features into the project CRS.</p><h2 id="More-than-one-seismic-profile" tabindex="-1">More than one seismic profile <a class="header-anchor" href="#More-than-one-seismic-profile" aria-label="Permalink to &quot;More than one seismic profile {#More-than-one-seismic-profile}&quot;">​</a></h2><p><code>seismic_data</code> can be a list. Each entry is a path, or a named tuple:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">seismic_data </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ata</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eismic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ine1.sgy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    (path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ata</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">eismic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ine2.sgy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, label </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Line 2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, line_color </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :red</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>A named tuple can have these fields: <code>path</code>, <code>label</code>, <code>line_color</code>, <code>sample_spacing_m</code> and <code>top_z_m</code>. A field that you do not give uses the value from the <code>seismic</code> settings.</p><p>If you set <code>seismic.trace_xy = :auto</code>, TerraScope uses the first trace header that has coordinates: source, receiver group or CDP.</p><h2 id="Point-files" tabindex="-1">Point files <a class="header-anchor" href="#Point-files" aria-label="Permalink to &quot;Point files {#Point-files}&quot;">​</a></h2><p>An <code>.xyz</code> file has one record on each line. A record has four columns:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>longitude  latitude  elevation  value</span></span></code></pre></div><p>You can also use easting and northing in a projected CRS. TerraScope reprojects the points into the project CRS. For a model, it then resamples the values onto the model mesh.</p><h3 id="Source-CRS-detection" tabindex="-1">Source CRS detection <a class="header-anchor" href="#Source-CRS-detection" aria-label="Permalink to &quot;Source CRS detection {#Source-CRS-detection}&quot;">​</a></h3><p>An <code>.xyz</code> file does not tell its CRS. How does TerraScope find it?</p><p>Look at the numbers. A longitude is between −180 and 180, and a latitude is between −90 and 90. A projected CRS puts survey data tens or hundreds of kilometres from its false origin. Thus the two types of coordinates do not overlap, and the size of the numbers tells the CRS. TerraScope reads the file as WGS84 longitude/latitude, or as coordinates that are already in the project CRS.</p><p>But one case is not clear. If the two columns are both between −90 and 90, which column is the longitude? TerraScope then uses the area of use of the project CRS. Thus a file with latitude in the first column also goes to the correct location.</p><p>TerraScope always reads <code>.prj</code> files and ModEM origins from the files.</p>`,35)])])}const y=t(o,[["render",n]]);export{g as __pageData,y as default};
